-- Requires user_file_storage proposal applied. SQL/metadata tests ONLY, not binary HTTP tests.
-- Run as trusted postgres, transactional fixtures roll back. Never remove ROLLBACK.
begin;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.rejects(statement text) returns boolean language plpgsql as $$ begin execute statement; return false;
 exception when insufficient_privilege or invalid_parameter_value or no_data_found or check_violation then return true; end $$;
insert into auth.users(id) values('41111111-1111-4111-8111-111111111111'),('42222222-2222-4222-8222-222222222222'),('43333333-3333-4333-8333-333333333333');
update public.user_roles set role='admin' where user_id='43333333-3333-4333-8333-333333333333';
select public.enable_user_file_storage(true);
create temp table ids(key text primary key,id uuid,path text);
grant all on ids to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','43333333-3333-4333-8333-333333333333',true);
insert into ids(key,id) values('card',(public.admin_save_card_data('cards','{"title":"Private photo fixture","slug":"__private_photo_fixture","status":"draft"}')->>'id')::uuid);
select public.admin_save_card_data('card_templates',jsonb_build_object('card_id',(select id from ids where key='card'),'template_key','__private_photo_fixture','layout_config','{"design_key":"photo-keepsake","canvas":{"width":600,"height":800},"photo_upload":true}'::jsonb));
select public.admin_save_card_data('personalization_fields',jsonb_build_object('card_id',(select id from ids where key='card'),'field_key','recipient_name','label','Recipient','field_type','text','is_required',true));
select public.admin_save_card_data('personalization_fields',jsonb_build_object('card_id',(select id from ids where key='card'),'field_key','recipient_photo','label','Photo','field_type','image','is_required',false,'config','{}'::jsonb));
select public.admin_save_card_data('cards','{"status":"published"}',(select id from ids where key='card'));
select set_config('request.jwt.claim.sub','41111111-1111-4111-8111-111111111111',true);
insert into ids(key,id) values('draft',(public.create_card_draft((select id from ids where key='card'),'{"recipient_name":"Owner A"}')).id);
insert into ids select 'avatar',id,storage_path from public.prepare_user_upload('avatar');
insert into ids select 'photo',id,storage_path from public.prepare_user_upload('draft',(select id from ids where key='draft'));
select pg_temp.ok((select path like auth.uid()::text||'/avatars/%.png' from ids where key='avatar'),'avatar path derived from auth identity');
select pg_temp.ok(pg_temp.rejects($q$update public.profiles set avatar_url=(select path from ids where key='avatar') where id=auth.uid()$q$),'unvalidated file cannot be attached');
select pg_temp.ok(pg_temp.rejects($q$insert into storage.objects(bucket_id,name) values('user-uploads',(select path from ids where key='avatar'))$q$),'direct uploads bypassing trusted image validation denied');
select pg_temp.ok(pg_temp.rejects($q$select public.finish_user_upload((select id from ids where key='avatar'),100,1,1)$q$),'browser cannot finalize images');
select pg_temp.ok(pg_temp.rejects($q$select public.update_card_draft((select id from ids where key='draft'),'{"recipient_name":"Owner A","recipient_photo":"another/path.png"}')$q$),'manual photo path in personalization rejected');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'user-uploads',path,'{"size":100,"mimetype":"image/png"}' from ids where key in ('avatar','photo');
select public.finish_user_upload((select id from ids where key='avatar'),100,1,1);
select public.finish_user_upload((select id from ids where key='photo'),100,1,1);
set local role authenticated;
select set_config('request.jwt.claim.sub','41111111-1111-4111-8111-111111111111',true);
select pg_temp.ok((select count(*)=2 from storage.objects where bucket_id='user-uploads'),'owner reads validated files');
insert into ids(key,id) values('generation',(public.generate_card((select id from ids where key='draft'),0)->'generated_card'->>'id')::uuid);
select pg_temp.ok((select uploaded_image_path=(select path from ids where key='photo') from public.generated_cards where id=(select id from ids where key='generation')),'generation captures photo snapshot');
select set_config('request.jwt.claim.sub','42222222-2222-4222-8222-222222222222',true);
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='user-uploads'),'other user cannot read private images');
select pg_temp.ok((select count(*)=0 from public.user_uploads),'upload registry isolated');
select pg_temp.ok((select count(*)=0 from public.card_drafts where id=(select id from ids where key='draft')),'other user cannot read draft');
select pg_temp.ok((select count(*)=0 from public.get_generated_cards((select id from ids where key='generation'))),'other user cannot read generated snapshot');
select pg_temp.ok(pg_temp.rejects($q$update public.profiles set avatar_url=(select path from ids where key='avatar') where id=auth.uid()$q$),'cannot reference another avatar');
select pg_temp.ok(pg_temp.rejects($q$update public.card_drafts set uploaded_image_path=(select path from ids where key='photo') where id=(select id from ids where key='draft')$q$),'cannot manually edit private draft paths');
select pg_temp.ok(pg_temp.rejects($q$select public.prepare_user_upload('draft',(select id from ids where key='draft'))$q$),'cannot upload for another draft');
select pg_temp.ok(pg_temp.rejects($q$select public.remove_user_file('draft',(select id from ids where key='draft'))$q$),'cannot remove another draft photo');
select pg_temp.ok(pg_temp.rejects($q$update public.user_roles set role='admin' where user_id=auth.uid()$q$),'role escalation denied');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_asset_settings()$q$),'regular user admin operation denied');
select set_config('request.jwt.claim.sub','41111111-1111-4111-8111-111111111111',true);
select public.remove_user_file('draft',(select id from ids where key='draft'));
reset role;
select pg_temp.ok((select state='ready' from public.user_uploads where id=(select id from ids where key='photo')),'generation photo retained after removal from draft');
delete from public.generated_cards where id=(select id from ids where key='generation');
select pg_temp.ok(exists(select 1 from private.user_file_cleanup where storage_path=(select path from ids where key='photo')),'unused photo queued after final reference removed');
set local role anon;
select pg_temp.ok((select count(*)=0 from storage.objects where bucket_id='user-uploads'),'anonymous private read denied');
select pg_temp.ok(pg_temp.rejects($q$select public.prepare_user_upload('avatar')$q$),'anonymous upload authorization denied');
reset role;
select pg_temp.ok(not has_function_privilege('authenticated','public.confirm_user_file_cleanup(text,text)','execute'),'cleanup finalization trusted only');
select 'Private file SQL authorization checks passed; fixtures rolled back.' as result;
rollback;
